'use strict';
let managedEmployees=[];
async function loadEmployees(){if(currentUser?.role!=='manager')return;try{const result=await api('employees');if(currentUser?.role!=='manager')return;managedEmployees=result.employees;$('employeeList').innerHTML='<div class="table-wrap"><table><thead><tr><th>NHÂN VIÊN</th><th>Tên đăng nhập</th><th>Vai trò công việc</th><th>Trạng thái</th><th></th></tr></thead><tbody>'+managedEmployees.map(e=>'<tr><td data-no-translate>'+esc(e.name)+'</td><td data-no-translate>'+esc(e.username)+'</td><td data-no-translate>'+esc(e.job)+'</td><td>'+(e.blocked?'Đã khóa':e.approved?'Hoạt động':'Chờ duyệt')+'</td><td><button class="outline" data-employee="'+esc(e.id)+'" data-action="profile">Xem hồ sơ</button> <button class="outline" data-employee="'+esc(e.id)+'" data-action="edit">Sửa thông tin</button> <button class="outline" data-employee="'+esc(e.id)+'" data-action="password">Đặt lại mật khẩu</button> <button class="outline" data-employee="'+esc(e.id)+'" data-action="'+(e.blocked?'unlock':'lock')+'">'+(e.blocked?'Mở khóa':'Khóa tài khoản')+'</button> <button class="outline" data-employee="'+esc(e.id)+'" data-action="delete">Xóa nhân viên</button></td></tr>').join('')+'</tbody></table></div>';$('employeeListError').textContent='';}catch(e){$('employeeList').innerHTML='';$('employeeListError').textContent=e.message;}}
$('employeeList').onclick=async event=>{const b=event.target.closest('[data-employee]');if(!b)return;const employee=managedEmployees.find(e=>e.id===b.dataset.employee),action=b.dataset.action;if(action==='delete'){if(!confirm(translateText('Xóa nhân viên khỏi danh sách? Tài khoản sẽ ngừng hoạt động, lịch sử được giữ lại.')))return;b.disabled=true;try{await api('delete',{type:'employee',id:employee.id});await refreshState();toast('Đã xóa');}catch(e){toast(e.message);b.disabled=false;}return;}if(action==='profile')return showEmployeeProfile(employee.id);if(action==='lock'||action==='unlock'){if(!confirm(translateText(action==='lock'?'Khóa tài khoản và giữ lịch sử ca, lương?':'Mở khóa tài khoản?')))return;b.disabled=true;try{await api('employees',{id:employee.id,action});await refreshState();toast('Đã cập nhật nhân viên');}catch(e){toast(e.message);b.disabled=false;}return;}const f=$('editEmployeeForm');f.reset();f.elements.id.value=employee.id;f.elements.action.value=action;f.elements.name.value=employee.name;f.elements.job.value=employee.job;$('employeeInfoFields').hidden=action!=='edit';$('employeePasswordField').hidden=action!=='password';f.elements.name.required=action==='edit';f.elements.password.required=action==='password';$('editEmployeeError').textContent='';$('editEmployeeDialog').showModal();};
$('editEmployeeForm').onsubmit=async event=>{event.preventDefault();const f=event.target,b=f.querySelector('button.primary');b.disabled=true;try{await api('employees',{id:f.elements.id.value,action:f.elements.action.value,name:f.elements.name.value,job:f.elements.job.value,password:f.elements.password.value});f.reset();$('editEmployeeDialog').close();await refreshState();toast('Đã cập nhật nhân viên');}catch(e){$('editEmployeeError').textContent=e.message;}finally{b.disabled=false;}};
$('managementAddEmployee').onclick=()=>$('employeeDialog').showModal();
